30	  process.stderr.write(`${prog}: error: ${message}\n`);
31	  process.exit(2);
32	}
33	
34	function printHelp(prog) {
35	  process.stdout.write(
36	    usageLine(prog) +
37	      '\n' +
38	      'options:\n' +
39	      '  -h, --help  show this help message and exit\n' +
40	      '  --a A\n' +
41	      '  --b B\n'
42	  );
43	  process.exit(0);
44	}
45	
46	export function parseArgs(argv, prog) {
47	  const values = {};
48	  const leftovers = [];
49	  let i = 0;
50	  let sawDoubleDash = false;
51	
52	  while (i < argv.length) {
53	    const token = argv[i];
54	
55	    if (sawDoubleDash) {
56	      leftovers.push(token);
57	      i += 1;
58	      continue;
59	    }
60	
61	    if (token === '--') {
62	      sawDoubleDash = true;
63	      i += 1;
64	      continue;
65	    }
66	
67	    if (token.startsWith('--')) {
68	      const eq = token.indexOf('=');
69	      const name = eq === -1 ? token : token.slice(0, eq);
70	      const explicitValue = eq === -1 ? null : token.slice(eq + 1);
71	
72	      // Exact match wins; otherwise unambiguous prefix abbreviation.
73	      let match = LONG_OPTIONS.includes(name) ? name : null;
74	      if (match === null) {
75	        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
76	        if (candidates.length === 1) {
77	          match = candidates[0];
78	        } else if (candidates.length > 1) {
79	          errorExit(
80	            prog,
81	            `ambiguous option: ${name} could match ${candidates.join(', ')}`
82	          );
83	        }
84	      }
85	
86	      if (match === null) {
87	        leftovers.push(token);
88	        i += 1;
89	        continue;
90	      }
91	
92	      if (match === '--help') {
93	        printHelp(prog);
94	      }
95	
96	      // --a / --b take exactly one argument.
97	      if (explicitValue !== null) {
98	        values[match] = explicitValue;
99	        i += 1;
100	        continue;
101	      }
102	      const next = argv[i + 1];
103	      if (next === undefined || isOptionLike(next)) {
104	        errorExit(prog, `argument ${match}: expected one argument`);
105	      }
106	      values[match] = next;
107	      i += 2;
108	      continue;
109	    }
110	
111	    if (isOptionLike(token)) {
112	      if (token === '-h') {
113	        printHelp(prog);
114	      }
115	      leftovers.push(token);
116	      i += 1;
117	      continue;
118	    }
119	
120	    // No positionals are defined, so any plain token is a leftover.
121	    leftovers.push(token);
122	    i += 1;
123	  }
124	
125	  // argparse reports missing required arguments before unrecognized ones.
126	  const missing = REQUIRED.filter((opt) => !(opt in values));
127	  if (missing.length > 0) {
128	    errorExit(
129	      prog,
130	      `the following arguments are required: ${missing.join(', ')}`
131	    );
132	  }
133	
134	  if (leftovers.length > 0) {
135	    errorExit(prog, `unrecognized arguments: ${leftovers.join(' ')}`);
136	  }
137	
138	  return { a: values['--a'], b: values['--b'] };
139	}

